  Future<void> load() async {
    try {
      bank=(jsonDecode(await rootBundle.loadString('assets/data/questions.json')) as List).map((x)=>Question(x)).toList();
      byId={for(final q in bank) q.id:q};coverage=jsonDecode(await rootBundle.loadString('assets/data/coverage.json'));
      prefs=await SharedPreferences.getInstance();
      try {
        final raw=prefs!.getString(storageKey);
        if(raw!=null){final stored=jsonDecode(raw);data={...data,...Map<String,dynamic>.from(stored)};}
        else {
          final oldSaved=prefs!.getString('${coverage['datasetId']}.saved');
          final oldAttempts=prefs!.getString('${coverage['datasetId']}.attempts');
          if(oldSaved!=null)data['saved']=jsonDecode(oldSaved);
          if(oldAttempts!=null){data['attempts']=jsonDecode(oldAttempts);final m=memory;for(final a in attempts){for(final x in a['answers']){engine.record(m,x['id'],x['correct'],a['date'],now:DateTime.parse(a['date']).millisecondsSinceEpoch);}}data['memory']=m;}
        }
        if(data['active']!=null&&!engine.validSession(data['active'],byId)){final original=prefs!.getString(storageKey);if(original!=null&&!prefs!.containsKey('$storageKey.recovery'))await prefs!.setString('$storageKey.recovery',original);}
        data=engine.sanitizeState(data,bank,coverage['retiredQuestionIds']??[]);
        final scope=data['scope'];if(scope is Map&&sources.any((s)=>s['id']==scope['source'])&&['original','modified'].contains(scope['variant'])){source=scope['source'];variant=scope['variant'];}
        data['saved']=saved.where((id)=>byId.containsKey(id)&&!byId[id]!.reviewOnly).toList();
        final cleaned=memory;cleaned.removeWhere((id,_)=>!byId.containsKey(int.tryParse(id))||byId[int.tryParse(id)]!.reviewOnly);data['memory']=cleaned;
        data['attempts']=attempts.where((a)=>a['answers'] is List&&(a['answers'] as List).isNotEmpty&&(a['answers'] as List).every((x)=>(byId.containsKey(x['id'])||(coverage['retiredQuestionIds'] as List? ?? []).contains(x['id']))&&x['correct'] is bool)).toList();
        if(data['active']!=null && !(data['active']['ids'] as List).every((id)=>byId.containsKey(id)&&!byId[id]!.reviewOnly))data['active']=null;
      } catch(_){try{final raw=prefs!.getString(storageKey);if(raw!=null&&!prefs!.containsKey('$storageKey.recovery'))await prefs!.setString('$storageKey.recovery',raw);}catch(_){} data=engine.sanitizeState(data,bank,coverage['retiredQuestionIds']??[]);data['active']=null;}
      await persist();
    } catch(_){error='تعذّر تحميل مساحة التعلّم. حاول مجددًا.';}
    if(mounted)setState(()=>loading=false);
  }
  Future<bool> persist() async {data['scope']={'source':source,'variant':variant};try{final stored=await prefs?.setString(storageKey,jsonEncode(data));if(stored==true)return true;}catch(_){}if(mounted)message('تعذّر الحفظ المحلي. تحقق من مساحة الجهاز.');return false;}
  void message(String text){WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(text),behavior:SnackBarBehavior.floating));});}
  Future<bool> checkpoint() async {data['active']=session==null?null:jsonDecode(jsonEncode(session));return persist();}
  void record(int id,bool correct){final m=memory;engine.record(m,id,correct,session!['id']);data['memory']=m;}
  void toggleSave(int id){final a=saved;if(a.contains(id)){a.remove(id);}else{a.add(id);}setState(()=>data['saved']=a);persist();}
  void navigate(int i){if(session!=null){checkpoint();session=null;}setState((){tab=i;search='';section='';type='';listPage=0;});persist();}
  Future<void> start({int count=10,String topic='',String kind='',bool exam=false,bool review=false,List<int>? ids}) async {
    if(data['active']!=null&&session==null){final replace=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('بدء جلسة جديدة؟'),content:const Text('ستستبدل الجلسة غير المكتملة. تبقى إجاباتك المسجلة وأخطاؤك محفوظة.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ابدأ'))]));if(replace!=true)return;}
    final list=engine.plan(bank,memory,count:count,section:topic,type:kind,source:ids==null?source:'',variant:ids==null?variant:'',exam:exam,review:review,ids:ids);
    if(list.isEmpty){if(mounted)message('لا توجد أسئلة مطابقة الآن.');return;}
    if(list.every((q)=>q.sourceId==list.first.sourceId&&q.variant==list.first.variant)){source=list.first.sourceId;variant=list.first.variant;}
    setState((){session={'id':'${DateTime.now().microsecondsSinceEpoch}','ids':list.map((q)=>q.id).toList(),'index':0,'source':source,'variant':variant,'section':topic,'exam':exam,'review':review,'answers':<dynamic>[],'selected':'','revealed':false,'hints':0,'options':<String>[]};prepare();});
    await checkpoint();
  }
  void prepare(){
    final current=q,m=q.mode;session!['revealed']=false;session!['hints']=0;session!['currentRecorded']=false;inputController.clear();
    final old=List<String>.from(data['orders']['${q.id}']??[]);
    final options=engine.varied(current.options,old);
    if(m=='single'&&old.isNotEmpty&&options.indexOf(q.answer)==old.indexOf(q.answer)&&options.length>1)options.add(options.removeAt(0));
    if(m=='multi'&&old.length==options.length&&old.isNotEmpty&&List.generate(options.length,(i)=>i).every((i)=>q.correct.contains(options[i])==q.correct.contains(old[i])))options.add(options.removeAt(0));
    session!['options']=options;
    if(m=='single'||m=='multi')data['orders']['${q.id}']=options;
    session!['selected']=(m=='multi'||m=='order'||m=='match'||m=='group')?<String>[]:'';
    if(m=='order'){final list=engine.shuffled(q.options);if(evaluateAnswer(q,list))list.add(list.removeAt(0));session!['selected']=list;}
    if(m=='match'){session!['selected']=List<String>.filled(q.pairs.length,'');session!['options']=engine.varied(q.pairs.map((p)=>p['right'] as String).toList(),old);data['orders']['${q.id}']=session!['options'];session!['pairOrder']=engine.shuffled(List.generate(q.pairs.length,(i)=>i));}
    if(m=='group'){session!['selected']=List<String>.filled(q.parts.length,'');session!['partOrder']=engine.shuffled(List.generate(q.parts.length,(i)=>i));}
  }
  void resume(){if(!engine.validSession(data['active'],byId)){data['active']=null;persist();message('الجلسة المحفوظة غير صالحة؛ تقدّمك المسجل باقٍ.');return;}setState((){session=Map<String,dynamic>.from(jsonDecode(jsonEncode(data['active'])));final items=(session!['ids'] as List).map((id)=>byId[id]!).toList();if(items.every((q)=>q.sourceId==items.first.sourceId&&q.variant==items.first.variant)){source=items.first.sourceId;variant=items.first.variant;}inputController.text=session!['selected'] is String?session!['selected']:'';});persist();finishIfReady();}
  Future<void> pause() async {final id=session?['id'];final stored=await checkpoint();if(!mounted||session?['id']!=id)return;setState(()=>session=null);message(stored?'حُفظت جلستك. يمكنك العودة متى أحببت.':'لم يتم الحفظ على الجهاز. الجلسة مؤقتة فقط؛ لا تغلق التطبيق قبل توفير مساحة.');}
  void check(){if(!ready||revealed)return;if(session!['exam']==true&&q.selfGraded){next(null);}else{if(!q.selfGraded){record(q.id,evaluateAnswer(q,session!['selected']));session!['currentRecorded']=true;}setState(()=>session!['revealed']=true);checkpoint();}}
  void next(bool? correct,{bool skipped=false}){
    final current=q;
    if(correct!=null&&session!['currentRecorded']!=true)record(current.id,correct);
    setState((){
      (session!['answers'] as List).add({'id':current.id,'selected':jsonDecode(jsonEncode(session!['selected'])),'correct':correct,'self':current.selfGraded,'hints':session!['hints'],'skipped':skipped});
      session!['index']++;
      if(session!['index']<(session!['ids'] as List).length)prepare();
    });checkpoint();finishIfReady();
  }
  void assess(int index,bool correct){final a=session!['answers'][index];if(a['correct']!=null)return;record(a['id'],correct);setState(()=>a['correct']=correct);checkpoint();finishIfReady();}
  Map<String,dynamic>? lastResult;
  void finishIfReady(){if(session==null||session!['index']<(session!['ids'] as List).length)return;if((session!['answers'] as List).any((a)=>a['correct']==null))return;
    final a={'id':session!['id'],'date':DateTime.now().toIso8601String(),'exam':session!['exam'],'source':session!['source'],'variant':session!['variant'],'section':session!['section']??'','answers':session!['answers']};
    setState((){if(!attempts.any((v)=>v['id']==a['id']))attempts.add(a);lastResult=a;data['active']=null;session=null;tab=6;});persist();
  }
