  Future<void> preferences() async {await showDialog<void>(context:context,builder:(c)=>StatefulBuilder(builder:(c,update){void setting(String key,dynamic value){setState(()=>settings[key]=value);update((){});persist();}return AlertDialog(title:const Text('على مقاس راحتك'),content:SizedBox(width:420,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[SwitchListTile(title:const Text('نص أكبر وأسهل للقراءة'),value:settings['large']==true,onChanged:(v)=>setting('large',v)),SwitchListTile(title:const Text('حركات هادئة وانتقالات ناعمة'),value:settings['motion']==true,onChanged:(v)=>setting('motion',v)),SwitchListTile(title:const Text('وضع التركيز أثناء الحل'),value:settings['focus']==true,onChanged:(v)=>setting('focus',v)),DropdownButton<int>(value:settings['goal'],items:[5,10,15,20].map((n)=>DropdownMenuItem(value:n,child:Text('هدفي اليومي: $n أسئلة'))).toList(),onChanged:(v)=>setting('goal',v!)),note('التدريبات من sorular.txt و2.txt و3.txt، كل ملف مستقل. التصحيح يقيس موافقة المرجع، وليس توثيقًا لصحة أحكامه أو نقوله. يُحفظ التقدّم على هذا الجهاز فقط.'),Text('${coverage['trainedUnits']??0} وحدة نصية لها تدريبات. تبقى القوالب الفارغة والمقطع النقدي خارج التقييم.',style:const TextStyle(fontSize:12,color:muted))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('تم'))]);}));}
